navbar.handleNavClickLink:
[KOK] handleNavClick(link.id)}
                className={`w-full text-left px-4 py-3 rounded-xl text-sm font-semibold transition ${
                  activeTab === link.id
                    ? 'bg-amber-500/10 text-amber-400'
                    : 'text-slate-300 hover:bg-slate-800'
                }`}>
                {link.label}

bookingModal.setBookingDateETar:
[KOK] setBookingDate(e.target.value)}
                  className="w-full px-4 py-3.5 rounded-xl bg-slate-950/80 border border-slate-700/60 text-white text-sm focus:outline-none focus:border-amber-500/60 transition-colors"
                />

bookingModal.setPaymentMethodMet:
[KOK] setPaymentMethod(method)}
                    className={`py-3.5 rounded-xl border text-sm font-bold transition-all ${
                      paymentMethod === method
                        ? 'bg-amber-500/20 border-amber-500 text-amber-400 shadow-inner'
                        : 'bg-slate-950/50 border-slate-800/80 text-slate-400 hover:border-slate-700'
                    }`}
                  >
                    {method}

adminPayments.setActiveTabTab:
[KOK] setActiveTab(tab)}
            className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
              activeTab === tab 
                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' 
                : 'text-slate-400 hover:text-white hover:bg-slate-800/50'
            }`}
          >
            {tab === 'all' ? 'All Transactions' : tab === 'pending_payouts' ? 'Pending Payouts' : 'Refund Requests'}
